ZcyIiE#YOx9u*|?wG9Tx)r@oPYLB{*_6+ZCSblp2ms8*mcCcO2eIp)*k*MO-D!umDvs1`r#@Xmp<z4qMq6!>FaPJF+V!{q&k*Fe`;c@dyEWB*X~R9=-mkzXoJ4_KW%cE>+sc}G!U{fip|TMelCDPWm=ARbq>n&OFz>w&j`Z?^wU@$cOTtcBytPsd64k3YOp%08AL%cAHD%lfBEmVNo^AM}KiWP$I;Oz4mQ0d(B1ZU'
FILES = ["src/game/fighter.ts", "src/game/game.ts", "src/game/kits.ts", "src/game/ai.ts", "src/ui/GameView.tsx"]

def patch_text(original, steps, rel):
    output=original
    for i,step in enumerate(steps,1):
        old,new=step["old"],step["new"]
        count=output.count(old)
        expected=5 if rel=="src/game/fighter.ts" and "this.kiraAirKicks = 0; this.kiraAirBuffered" in old else 1
        if count!=expected:
            raise ValueError(f"{rel} step {i}: expected {expected} copies of a source anchor; found {count}. Your game version differs; no V9 changes were written.")
        output=output.replace(old,new)
    return output

def main():
    here=pathlib.Path(__file__).resolve().parent
    roots=[pathlib.Path(sys.argv[1]).resolve()] if len(sys.argv)>1 else [here, here/"web",pathlib.Path.cwd(),pathlib.Path.cwd()/"web"]
    root=next((p for p in roots if (p/"src/game/fighter.ts").is_file()),None)
    if root is None:
        print("ERROR: Place this installer in fight-royale/web, or pass the web folder path as argument.")
        return 2
    fighter=(root/"src/game/fighter.ts").read_text(encoding="utf8")
    hud=(root/"src/ui/GameView.tsx").read_text(encoding="utf8")
    if PATCH in fighter and "DreadfallTempoMeter" in hud:
        print("Nythera V9 is already installed. No files changed.")
        return 0
    if "ZENITH_BASIC_DMG_25P_V8" not in (root/"src/game/kits.ts").read_text(encoding="utf8"):
        print("Earlier V8 update not detected; applying bundled V8 improvements first...")
        source=zlib.decompress(base64.b85decode(V8_INSTALLER))
        with tempfile.TemporaryDirectory(prefix="fr_nythera_bootstrap_") as td:
            bootstrap=pathlib.Path(td)/"v8.py"
            bootstrap.write_bytes(source)
            result=subprocess.run([sys.executable,str(bootstrap),str(root)],check=False)
            if result.returncode:
                print("V8 compatibility update failed. No V9 changes attempted.")
                return result.returncode
    steps=json.loads(zlib.decompress(base64.b85decode(DATA)))
    pending=[]
    try:
        for rel,changes in steps.items():
            path=root/rel
            if not path.is_file():raise FileNotFoundError(rel)
            before=path.read_text(encoding="utf8")
            after=patch_text(before,changes,rel)
            if after != before: pending.append((path,before,after))
        if not pending:
            print("Already up to date.")
            return 0
        stamp=datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        backups=[]
        try:
            for path,_,_ in pending:
                backup=path.with_name(path.name+".before_"+PATCH+"_"+stamp+".bak")
                shutil.copy2(path,backup)
                backups.append((path,backup))
            for path,_,after in pending:
                tmp=path.with_name(path.name+"."+PATCH+".tmp")
                tmp.write_text(after,encoding="utf8")
                tmp.replace(path)
                print("UPDATED:",path.relative_to(root))
        except BaseException:
            for path,backup in backups:
                shutil.copy2(backup,path)
            raise
    except Exception as exc:
        print("ERROR:",exc)
        return 3
    print("\nSUCCESS — NYTHERA V9")
    print("  - Moonfloat Orbit Marks: 5 maximum, 25s duration, visible in opponent HUD")
    print("  - Dreadfall damage: +0.10x speed per actual hit, 14 hits max (2.40x)")
    print("  - Speed bonus stays until the current round ends, even after stance switching")
    print("  - Four airborne scythe slices per jump, each with separate dodge/block/parry/clash")
    print("  - AI may tap through Nythera's aerial chain; online snapshots include the tempo")
    print("NEXT: run npx tsc --noEmit -p . and npm run dev")
    return 0

if __name__=="__main__":sys.exit(main())
